public long arrayManipulation(int n, int[][] ops) {
    long[] diff = new long[n + 2];
    for (int[] op : ops) {
        int a = op[0], b = op[1], k = op[2];
        diff[a] += k;
        diff[b + 1] -= k;
    }
    long running = 0, best = 0;
    for (int i = 1; i <= n; i++) {
        running += diff[i];
        best = Math.max(best, running);
    }
    return best;
}

